package EnergyCommunity.core.mcpServer.agent.model;

import java.util.List;

/**
 * Encapsulates a single turn response from the LLM provider.
 * The model may either request one or more MCP tool calls ({@link #hasToolCalls()})
 * or conclude with a final optimization summary.
 *
 * @param assistantText Textual explanation or final summary generated by the LLM
 * @param toolCalls     List of MCP tool calls requested by the LLM in this step
 */
public record LlmResponse(
        String assistantText,
        List<LlmToolCall> toolCalls
) {
    public boolean hasToolCalls() {
        return toolCalls != null && !toolCalls.isEmpty();
    }
}
